// ============================================
// HELPER: Create pixelated/blocky geometry
// ============================================
function createBlock(width, height, depth, widthSegs = 1, heightSegs = 1, depthSegs = 1) {
    const geo = new THREE.BoxGeometry(width, height, depth, widthSegs, heightSegs, depthSegs);
    // Merge vertices for flat shading
    geo.deleteAttribute('normal');
    geo.computeVertexNormals();
    return geo;
}

function createRoundedBlock(width, height, depth, radius = 0.05) {
    // Simulate rounded corners with beveled box
    const geo = new THREE.BoxGeometry(width, height, depth, 2, 2, 2);
    geo.deleteAttribute('normal');
    geo.computeVertexNormals();
    return geo;
}

