function createBreathingAnimation() {
    const tracks = [];
    const duration = 4.0;
    const times = [0, duration / 2, duration];
    
    // Torso subtle scale
    const torsoScaleTrack = new THREE.VectorKeyframeTrack(
        '.scale',
        times,
        [1, 1, 1,  1.005, 1.01, 1.005,  1, 1, 1]
    );
    tracks.push(torsoScaleTrack);

    // Head subtle bob
    const headPosTrack = new THREE.VectorKeyframeTrack(
        'headGroup.position',
        times,
        [0, 1.85, 0,  0, 1.855, 0,  0, 1.85, 0]
    );
    tracks.push(headPosTrack);

    const clip = new THREE.AnimationClip('breathing', duration, tracks);
    return clip;
}

