animations.push(breathingClip);

// Arm sway animation
function createArmSwayAnimation() {
    const tracks = [];
    const duration = 6.0;
    const times = [0, duration / 4, duration / 2, 3 * duration / 4, duration];
    
    // Left arm rotation
    const leftArmRotTrack = new THREE.QuaternionKeyframeTrack(
        'leftArm.quaternion',
        times,
        [
            0, 0, -0.075, 1,
            0, 0, -0.1, 1,
            0, 0, -0.075, 1,
            0, 0, -0.05, 1,
            0, 0, -0.075, 1
        ]
    );
    tracks.push(leftArmRotTrack);

    const clip = new THREE.AnimationClip('armSway', duration, tracks);
    return clip;
}

